/* eslint-env mocha */
const chai = require('chai')
const chaiAsPromised = require('chai-as-promised')
chai.use(chaiAsPromised)
const expect = chai.expect
const scraper = require('../scraper')

describe('Async Kleinanzeigen Scraper Test(s)', () => {
  it('eventually be fulfilled', () => {
    // expect(scraper()).to.be.a('string')
    return expect(scraper()).to.eventually.be.fulfilled
  })
  it('eventually return string', () => {
    // expect(scraper()).to.be.a('string')
    return expect(scraper()).to.eventually.be.a('string')
  })
})
